/* Reference glossary. Each entry: term, definition, and the topic ids where the idea is used.
   Kept in plain language; notation follows the EC1002 subject guide. */
window.GLOSSARY = [
  /* ── Foundations ── */
  { term: 'Scarcity', def: 'Resources are limited relative to wants, so every choice has a cost: using resources for one thing means not using them for another.', topics: ['ppf'] },
  { term: 'Opportunity cost', def: 'The value of the next best alternative given up. On a PPF it is the amount of one good sacrificed to produce one more unit of the other, the absolute value of the PPF’s slope.', topics: ['ppf'] },
  { term: 'Production possibility frontier (PPF)', def: 'The set of maximum output combinations of two goods an economy can produce with its resources and technology. Points inside are inefficient; points outside are unattainable.', topics: ['ppf'] },
  { term: 'Absolute advantage', def: 'Being the lowest-cost producer of a good: producing it with fewer inputs per unit than another producer (more output per worker).', topics: ['ppf'] },
  { term: 'Comparative advantage', def: 'Being able to produce a good at a lower opportunity cost than another producer. Specialisation according to comparative advantage lets both sides gain from trade.', topics: ['ppf'] },
  { term: 'Terms of trade', def: 'The rate at which one good exchanges for another in trade. Both parties gain if it lies between their two opportunity costs.', topics: ['ppf'] },
  { term: 'Ceteris paribus', def: '“Other things equal”: holding every other influence constant while one variable changes, so its effect can be isolated.', topics: ['supply-demand'] },
  { term: 'Marginal', def: 'The change in a total from a one-unit change in an activity, such as marginal cost, marginal revenue or marginal utility. Most optimising rules compare marginal values.', topics: ['costs', 'monopoly', 'consumer-choice'] },

  /* ── Markets ── */
  { term: 'Demand', def: 'The relationship between the price of a good and the quantity buyers are willing and able to buy, holding other factors constant.', topics: ['supply-demand'] },
  { term: 'Law of demand', def: 'Other things equal, quantity demanded falls as price rises, so demand curves slope downward.', topics: ['supply-demand'] },
  { term: 'Supply', def: 'The relationship between the price of a good and the quantity sellers are willing and able to sell, holding other factors constant.', topics: ['supply-demand'] },
  { term: 'Inverse demand / inverse supply', def: 'The demand or supply function solved for price, P = f(Q). This is the form plotted with price on the vertical axis.', topics: ['supply-demand'] },
  { term: 'Movement along vs shift of a curve', def: 'A change in the good’s own price moves along a curve. A change in anything else (income, tastes, input costs, technology) shifts the whole curve.', topics: ['supply-demand'] },
  { term: 'Market equilibrium', def: 'The price at which quantity demanded equals quantity supplied (Q_D = Q_S), so there is no shortage or surplus and no pressure for price to change.', topics: ['supply-demand'] },
  { term: 'Shortage (excess demand)', def: 'Quantity demanded exceeds quantity supplied at the current price. It usually arises below equilibrium, for example under a binding price ceiling.', topics: ['price-controls'] },
  { term: 'Surplus (excess supply)', def: 'Quantity supplied exceeds quantity demanded at the current price, for example under a binding price floor.', topics: ['price-controls'] },
  { term: 'Price ceiling', def: 'A legal maximum price. It binds only if set below equilibrium, causing a shortage and deadweight loss.', topics: ['price-controls'] },
  { term: 'Price floor', def: 'A legal minimum price, such as a minimum wage. It binds only if set above equilibrium, causing a surplus and deadweight loss.', topics: ['price-controls', 'labour-market'] },
  { term: 'Consumer surplus (CS)', def: 'The difference between what buyers are willing to pay and what they actually pay, summed over all units bought: the area below demand and above price.', topics: ['supply-demand', 'monopoly'] },
  { term: 'Producer surplus (PS)', def: 'The difference between the price sellers receive and the minimum they would accept, summed over all units sold: the area above supply and below price.', topics: ['supply-demand'] },
  { term: 'Social (total) surplus', def: 'Consumer surplus plus producer surplus (plus any tax revenue, minus any external cost). A competitive market with no externalities maximises it.', topics: ['supply-demand', 'tax-incidence'] },
  { term: 'Deadweight loss (DWL)', def: 'The fall in total surplus when the quantity traded differs from the efficient quantity, usually a triangle between demand and supply.', topics: ['price-controls', 'tax-incidence', 'monopoly', 'externalities', 'tariff'] },
  { term: 'Specific (per-unit) tax', def: 'A tax of a fixed amount t on each unit sold. It shifts supply up by t and drives a wedge P_b − P_s = t between buyers’ and sellers’ prices.', topics: ['tax-incidence'] },
  { term: 'Ad valorem tax', def: 'A tax set as a percentage of price, such as VAT. It rotates the supply curve rather than shifting it in parallel.', topics: ['tax-incidence'] },
  { term: 'Tax incidence', def: 'Who actually bears the burden of a tax. The less elastic side of the market bears more, whoever legally pays it.', topics: ['tax-incidence', 'labour-policy'] },
  { term: 'Subsidy', def: 'A payment to producers or consumers per unit. It lowers the price buyers pay, raises the price sellers get, and creates deadweight loss from overproduction.', topics: ['subsidy', 'tax-incidence'] },

  /* ── Elasticity ── */
  { term: 'Price elasticity of demand (PED)', def: 'The percentage change in quantity demanded divided by the percentage change in price: PED = (ΔQ/ΔP)(P/Q). As the guide recommends, keep the sign: demand is elastic if PED < −1, inelastic if −1 < PED < 0 and unit elastic at −1.', topics: ['elasticity'] },
  { term: 'Elastic / inelastic', def: 'Demand (or supply) is elastic when quantity responds more than proportionally to price, inelastic when it responds less than proportionally.', topics: ['elastic-inelastic', 'elasticity'] },
  { term: 'Perfectly elastic / perfectly inelastic demand', def: 'Perfectly elastic: a horizontal demand curve, |E| = ∞; buyers take any amount at one price and nothing above it. Perfectly inelastic: a vertical curve, |E| = 0; quantity does not respond to price at all.', topics: ['elastic-inelastic', 'elasticity'] },
  { term: 'Midpoint (arc) elasticity', def: 'Elasticity measured between two points using average quantity and average price as the bases, so the answer is the same in either direction.', topics: ['elasticity'] },
  { term: 'Point elasticity', def: 'Elasticity at a single point: (dQ/dP)·(P/Q). Along a straight-line demand curve it changes at every point even though the slope is constant.', topics: ['elasticity'] },
  { term: 'Income elasticity of demand (IED)', def: 'The percentage change in quantity demanded divided by the percentage change in income. Positive for normal goods, negative for inferior goods, above 1 for luxuries.', topics: ['income-elasticity', 'elasticity'] },
  { term: 'Cross-price elasticity (XED)', def: 'The percentage change in quantity of good A divided by the percentage change in the price of good B. Positive for substitutes, negative for complements.', topics: ['cross-price', 'elasticity'] },
  { term: 'Price elasticity of supply (PES)', def: 'The percentage change in quantity supplied divided by the percentage change in price. Usually larger in the long run.', topics: ['pes', 'elasticity'] },
  { term: 'Total revenue (TR)', def: 'Price times quantity sold. A price cut raises TR when demand is elastic and lowers it when demand is inelastic.', topics: ['elastic-inelastic', 'elasticity', 'monopoly'] },
  { term: 'Normal good', def: 'A good whose demand rises when income rises (IED > 0).', topics: ['income-elasticity', 'engel-derivation', 'elasticity', 'income-substitution'] },
  { term: 'Inferior good', def: 'A good whose demand falls when income rises (IED < 0).', topics: ['income-elasticity', 'engel-derivation', 'elasticity', 'income-substitution'] },
  { term: 'Luxury good', def: 'A normal good with income elasticity above 1: spending on it rises as a share of income as income grows.', topics: ['income-elasticity', 'elasticity'] },
  { term: 'Necessity', def: 'A normal good with income elasticity between 0 and 1: demand rises with income but less than proportionally, so its share of spending falls (Engel’s law for food).', topics: ['income-elasticity', 'engel-derivation'] },
  { term: 'Substitutes / complements', def: 'Substitutes are used instead of each other (XED > 0); complements are used together (XED < 0).', topics: ['elasticity'] },

  /* ── Consumer theory ── */
  { term: 'Utility', def: 'A numerical ranking of how much a consumer prefers bundles of goods. Only the ordering matters for choices (ordinal utility).', topics: ['consumer-choice'] },
  { term: 'Marginal utility (MU)', def: 'The extra utility from one more unit of a good, holding other goods constant. Usually diminishing.', topics: ['consumer-choice'] },
  { term: 'Completeness', def: 'An assumption on preferences: the consumer can rank any two bundles (prefers one, or is indifferent). It puts every bundle on some indifference curve.', topics: ['consumer-choice'] },
  { term: 'Transitivity', def: 'An assumption on preferences: if A is preferred to B and B to C, then A is preferred to C. It stops indifference curves crossing.', topics: ['consumer-choice'] },
  { term: 'Non-satiation', def: 'An assumption on preferences: more of a good is preferred to less. It makes indifference curves slope down; with satiation they can slope up.', topics: ['consumer-choice'] },
  { term: 'Indifference curve', def: 'All bundles that give the consumer the same utility. They slope down, do not cross, and are usually convex to the origin.', topics: ['consumer-choice', 'income-substitution', 'edgeworth'] },
  { term: 'Marginal rate of substitution (MRS)', def: 'The rate at which a consumer can swap Y for one more X while staying equally well off. As the slope of the indifference curve, MRS = ΔY/ΔX = −MU_X/MU_Y; it is often quoted as a positive number.', topics: ['consumer-choice', 'edgeworth'] },
  { term: 'Budget constraint', def: 'All bundles the consumer can just afford: P_X·X + P_Y·Y = M. Its slope is −P_X/P_Y.', topics: ['consumer-choice', 'income-substitution'] },
  { term: 'Utility-maximising bundle', def: 'The affordable bundle on the highest indifference curve. At an interior optimum the indifference curve is tangent to the budget line: MU_X/P_X = MU_Y/P_Y.', topics: ['consumer-choice'] },
  { term: 'Substitution effect', def: 'The change in quantity demanded from a change in relative prices alone, holding utility (real income) constant. It always moves against the price change.', topics: ['income-substitution'] },
  { term: 'Income effect', def: 'The change in quantity demanded caused by the change in purchasing power that a price change brings about.', topics: ['income-substitution'] },
  { term: 'Compensated budget line', def: 'A budget line at the new prices with just enough income to reach the original indifference curve. It separates the substitution effect from the income effect.', topics: ['income-substitution'] },
  { term: 'Giffen good', def: 'An inferior good whose income effect is larger than its substitution effect, so quantity demanded rises when its price rises.', topics: ['income-substitution'] },
  { term: 'Price–consumption curve (PCC)', def: 'The path traced by the optimal bundle as the price of one good changes, with income and the other price fixed. It is used to derive the demand curve.', topics: ['demand-derivation'] },
  { term: 'Income–consumption curve / Engel curve', def: 'The path of optimal bundles as income changes. Plotting quantity of one good against income gives its Engel curve.', topics: ['engel-derivation', 'income-elasticity', 'demand-derivation'] },
  { term: 'Horizontal summation', def: 'Building market demand (or supply) by adding the quantities of every individual at each price.', topics: ['market-demand', 'lr-industry'] },

  /* ── Production and costs ── */
  { term: 'Short run / long run (firm)', def: 'In the short run at least one input (usually capital) is fixed. In the long run all inputs are variable and firms can enter or exit.', topics: ['costs', 'lac-envelope'] },
  { term: 'Marginal product (MP)', def: 'The extra output from one more unit of an input, holding other inputs constant.', topics: ['mvp-demand', 'isoquant', 'labour-market'] },
  { term: 'Diminishing marginal returns', def: 'In the short run, adding more of a variable input to a fixed input eventually makes its marginal product fall. This is why short-run MC eventually rises.', topics: ['mvp-demand', 'costs'] },
  { term: 'Perfect substitutes in production', def: 'Inputs that can replace each other at a constant rate, as in Q = L + 2K. Isoquants are straight lines and the cost-minimising firm uses only the input that is cheaper per unit of output.', topics: ['isoquant'] },
  { term: 'Fixed proportions', def: 'A technology such as Q = min{L, K} in which inputs must be combined in a set ratio. Isoquants are L-shaped and input prices do not change the input mix.', topics: ['isoquant'] },
  { term: 'Isoquant', def: 'All combinations of inputs (L, K) that produce the same output.', topics: ['isoquant'] },
  { term: 'Isocost line', def: 'All input combinations with the same total cost: C = wL + rK. Its slope is −w/r.', topics: ['isoquant'] },
  { term: 'Marginal rate of technical substitution (MRTS)', def: 'The rate at which capital can be replaced by labour holding output constant: MRTS = −MP_L/MP_K, the slope of the isoquant.', topics: ['isoquant'] },
  { term: 'Least-cost input combination', def: 'Where the isocost line is tangent to the isoquant: MP_L/w = MP_K/r.', topics: ['isoquant'] },
  { term: 'Returns to scale', def: 'How output responds when all inputs are scaled up by the same proportion: increasing, constant or decreasing.', topics: ['isoquant', 'lac-envelope'] },
  { term: 'Fixed cost (FC)', def: 'Costs that do not vary with output in the short run, such as rent. They must be paid even at zero output.', topics: ['costs'] },
  { term: 'Variable cost (VC)', def: 'Costs that rise with output, such as wages and materials.', topics: ['costs'] },
  { term: 'Average total cost (ATC)', def: 'Total cost per unit: TC/Q = AFC + AVC.', topics: ['costs'] },
  { term: 'Marginal cost (MC)', def: 'The extra cost of producing one more unit: dTC/dQ. MC cuts AVC and ATC at their minimum points.', topics: ['costs', 'monopoly'] },
  { term: 'Long-run average cost (LAC)', def: 'The lowest average cost of producing each output when all inputs can vary. It is the lower envelope of the short-run average cost curves.', topics: ['lac-envelope'] },
  { term: 'Economies of scale', def: 'Long-run average cost falls as output rises, for example from specialisation, indivisibilities or bulk buying.', topics: ['lac-envelope', 'natural-monopoly'] },
  { term: 'Diseconomies of scale', def: 'Long-run average cost rises as output rises, typically from management and coordination problems.', topics: ['lac-envelope'] },
  { term: 'Minimum efficient scale (MES)', def: 'The smallest output at which long-run average cost reaches its minimum.', topics: ['lac-envelope'] },
  { term: 'Economic profit', def: 'Total revenue minus total cost, where cost includes the opportunity cost of all inputs, including the owner’s capital and time.', topics: ['costs', 'lr-industry'] },
  { term: 'Normal profit', def: 'Zero economic profit: revenue just covers all costs including opportunity costs, so the firm has no reason to leave or enter.', topics: ['costs', 'lr-industry'] },
  { term: 'Supernormal (abnormal) profit', def: 'Positive economic profit. In competitive markets it attracts entry.', topics: ['costs', 'lr-industry', 'monopoly'] },

  /* ── Market structures ── */
  { term: 'Perfect competition', def: 'Many small firms selling an identical product, with perfect information and free entry and exit. Each firm is a price taker.', topics: ['costs', 'lr-industry'] },
  { term: 'Price taker', def: 'A firm too small to affect the market price, so it faces a horizontal demand curve with P = MR = AR.', topics: ['costs'] },
  { term: 'Profit-maximising rule', def: 'Produce where marginal revenue equals marginal cost (MR = MC), with MC cutting MR from below.', topics: ['costs', 'monopoly'] },
  { term: 'Shutdown point', def: 'The price equal to minimum average variable cost. Below it, the firm loses less by closing (losing only fixed cost) than by producing.', topics: ['costs'] },
  { term: 'Break-even point', def: 'The price equal to minimum average total cost, where economic profit is zero.', topics: ['costs'] },
  { term: 'Firm’s short-run supply curve', def: 'The part of the marginal cost curve above minimum average variable cost.', topics: ['costs'] },
  { term: 'Long-run industry supply (LRS)', def: 'Price and quantity combinations after full entry and exit. Flat in a constant-cost industry, rising in an increasing-cost industry, falling in a decreasing-cost industry.', topics: ['lr-industry'] },
  { term: 'Allocative efficiency', def: 'Resources produce the goods people value most: price equals marginal cost (P = MC), so total surplus is maximised.', topics: ['lr-industry', 'monopoly'] },
  { term: 'Productive efficiency', def: 'Output is produced at the lowest possible average cost (at minimum LAC).', topics: ['lr-industry'] },
  { term: 'Monopoly', def: 'A single seller of a good with no close substitutes, protected by barriers to entry. It faces the market demand curve, so MR < P.', topics: ['monopoly'] },
  { term: 'Barriers to entry', def: 'Anything that stops new firms entering: legal protection (patents, licences), economies of scale, control of key inputs, network effects.', topics: ['entry-barriers', 'monopoly', 'natural-monopoly', 'contestable-markets'] },
  { term: 'Marginal revenue (MR)', def: 'The extra revenue from selling one more unit. For linear demand P = a − bQ, MR = a − 2bQ.', topics: ['monopoly'] },
  { term: 'Lerner index', def: 'A measure of market power: (P − MC)/P. It equals 1/|PED| at the profit-maximising output.', topics: ['oligopoly-compare', 'monopoly'] },
  { term: 'Price discrimination', def: 'Charging different prices to different buyers for the same good, for reasons other than cost differences. Perfect (first-degree) discrimination removes deadweight loss.', topics: ['monopoly'] },
  { term: 'First-degree (perfect) price discrimination', def: 'Charging each buyer their maximum willingness to pay for each unit. Output reaches the competitive level and there is no deadweight loss, but the firm captures all the surplus.', topics: ['price-discrimination'] },
  { term: 'Second-degree price discrimination', def: 'Prices that depend on the quantity or version bought, such as bulk discounts or basic and premium versions. Buyers sort themselves by what they choose.', topics: ['price-discrimination'] },
  { term: 'Third-degree price discrimination', def: 'Charging different prices to identifiable groups, such as students or off-peak travellers. The group with less elastic demand pays more, because each market sets MR = MC.', topics: ['price-discrimination'] },
  { term: 'Arbitrage', def: 'Buying where a good is cheap and reselling where it is dear. Price discrimination only works if arbitrage between buyer groups is prevented.', topics: ['price-discrimination'] },
  { term: 'Two-part tariff', def: 'A price made of a fixed fee plus a charge per unit, such as a connection fee and a per-unit price. The fee can capture surplus while the unit price is set near marginal cost. Not examinable in EC1002 (guide, Block 7).', topics: ['price-discrimination', 'natural-monopoly'] },
  { term: 'Kinked demand curve', def: 'An oligopoly model in which rivals match price cuts but ignore price rises, so demand is elastic above the current price and inelastic below it. The resulting gap in MR makes prices sticky. Not in the EC1002 syllabus: the guide’s Block 8 reading excludes it.', topics: ['kinked-demand'] },
  { term: 'Price rigidity (sticky prices)', def: 'Prices that stay unchanged despite moderate changes in costs or demand. The kinked demand model explains it by the vertical gap in marginal revenue. The kinked demand curve explanation is outside the EC1002 syllabus.', topics: ['kinked-demand'] },
  { term: 'Non-price competition', def: 'Competing through advertising, branding, quality, service or product features rather than price. Common in oligopolies where price changes invite retaliation.', topics: ['kinked-demand'] },
  { term: 'Natural monopoly', def: 'An industry where average cost falls over the whole range of market demand, so one firm can supply the market more cheaply than two or more.', topics: ['natural-monopoly', 'lac-envelope'] },
  { term: 'Average-cost (fair-return) pricing', def: 'A regulator sets price equal to average cost, giving the firm zero economic profit without a subsidy.', topics: ['natural-monopoly'] },
  { term: 'Marginal-cost pricing', def: 'A regulator sets price equal to marginal cost. Efficient, but a natural monopoly then makes a loss that must be covered by a subsidy.', topics: ['natural-monopoly'] },
  { term: 'Monopolistic competition', def: 'Many firms selling differentiated products with free entry. Short-run profits are competed away until each firm’s demand is tangent to its average cost.', topics: ['monopolistic-competition'] },
  { term: 'Excess capacity', def: 'In long-run monopolistic competition, firms produce less than the output at minimum average cost.', topics: ['monopolistic-competition'] },
  { term: 'Oligopoly', def: 'A market with a few interdependent firms, each of which must take its rivals’ reactions into account.', topics: ['oligopoly-compare', 'cournot'] },
  { term: 'Cournot competition', def: 'Oligopoly in which firms choose quantities simultaneously, each taking its rivals’ output as given.', topics: ['oligopoly-compare', 'cournot'] },
  { term: 'Contestable market', def: 'A market with free entry and costless exit (no sunk costs). The threat of hit-and-run entry forces even a single firm to price at average cost and earn only normal profit. Not in the EC1002 syllabus: the guide’s Block 8 reading excludes BVFD 10.6.', topics: ['contestable-markets'] },
  { term: 'Hit-and-run entry', def: 'Entering a market to take advantage of supernormal profit, then leaving before the incumbent can respond. Possible only when exit costs nothing. Not in the EC1002 syllabus: the guide’s Block 8 reading excludes BVFD 10.6.', topics: ['contestable-markets'] },
  { term: 'Sunk cost', def: 'A cost that cannot be recovered once incurred, even by leaving the market, such as advertising or specialised equipment. Sunk costs, not fixed costs as such, are what deter entry.', topics: ['contestable-markets', 'entry-barriers'] },
  { term: 'Limit pricing', def: 'Setting a price below the monopoly level, with output high enough that the demand left for an entrant would not cover its costs, to deter entry.', topics: ['entry-barriers'] },
  { term: 'Limit price', def: 'The highest price that still deters entry: the price at which an entrant’s best profit on the residual demand is zero.', topics: ['entry-barriers'] },
  { term: 'Residual demand', def: 'The part of market demand left for one firm once the others’ output is taken as given.', topics: ['price-leadership', 'collusion', 'entry-barriers', 'stackelberg'] },
  { term: 'Blockaded entry', def: 'Entry that is unprofitable even when the incumbent behaves as an unconstrained monopolist, so no strategic action is needed.', topics: ['entry-barriers'] },
  { term: 'Strategic barriers to entry', def: 'Deliberate actions by incumbents that make entry less attractive: limit pricing, excess capacity, predatory pricing, brand proliferation, heavy advertising, exclusive contracts.', topics: ['entry-barriers'] },
  { term: 'Predatory pricing', def: 'Cutting price below cost (in BVFD, below average variable cost) to drive out a rival or deter entry, then raising it again. Usually illegal under competition law.', topics: ['entry-barriers'] },
  { term: 'Network effects', def: 'When a product becomes more valuable the more people use it, such as social networks or payment systems. They can make it hard for a newcomer to attract users.', topics: ['entry-barriers'] },
  { term: 'Absolute cost advantage', def: 'An incumbent’s lower costs at every output, from better technology, cheaper inputs or experience, which an entrant cannot match.', topics: ['entry-barriers'] },
  { term: 'X-inefficiency', def: 'Costs above the minimum possible because a firm protected from competition has weak incentives to control them. The threat of entry in a contestable market reduces it.', topics: ['contestable-markets'] },
  { term: 'Game theory', def: 'The study of strategic decisions, where each player’s payoff depends on the choices of others. Used to analyse oligopoly, auctions, bargaining and policy.', topics: ['game-theory'] },
  { term: 'Payoff matrix (normal form)', def: 'A table listing each combination of the players’ strategies and the payoff each player receives, written (row player, column player).', topics: ['game-theory', 'prisoners-dilemma'] },
  { term: 'Dominant strategy', def: 'A strategy that gives a player a higher payoff than any alternative whatever the other players do.', topics: ['game-theory', 'prisoners-dilemma'] },
  { term: 'Iterated elimination of dominated strategies', def: 'Repeatedly removing strategies that a player would never choose because another strategy always does better, then re-examining the smaller game.', topics: ['game-theory'] },
  { term: 'Mixed strategy', def: 'Choosing among pure strategies at random with set probabilities. In a mixed equilibrium each player’s probabilities make the other player indifferent between their strategies.', topics: ['game-theory'] },
  { term: 'Coordination game', def: 'A game in which players gain from making matching choices, such as adopting the same standard. It typically has more than one Nash equilibrium.', topics: ['game-theory'] },
  { term: 'Zero-sum game', def: 'A game in which one player’s gain is exactly the other’s loss, such as matching pennies. There is no outcome that makes both better off.', topics: ['game-theory'] },
  { term: 'Prisoner’s dilemma', def: 'A game where each player has a dominant strategy to defect, yet both would be better off if both cooperated. The equilibrium is Pareto inefficient; cartels face this problem.', topics: ['prisoners-dilemma', 'game-theory'] },
  { term: 'Repeated game', def: 'The same game played over and over. With an indefinite horizon, the threat of future punishment can sustain cooperation that would fail in a single round.', topics: ['prisoners-dilemma'] },
  { term: 'Grim trigger strategy', def: 'Cooperate until the rival defects once, then defect for ever. Sustains cooperation if δ ≥ (T − R)/(T − P).', topics: ['collusion', 'prisoners-dilemma'] },
  { term: 'Tit-for-tat', def: 'Cooperate in the first round, then copy whatever the rival did in the previous round. A simple, forgiving strategy that does well in repeated prisoner’s dilemmas.', topics: ['prisoners-dilemma'] },
  { term: 'Discount factor (δ)', def: 'How much a payoff one period ahead is worth today, between 0 and 1. A higher δ means a more patient player.', topics: ['prisoners-dilemma'] },
  { term: 'Backward induction', def: 'Solving a sequential game by starting with the last move, finding each player’s best choice there, and working back to the first move.', topics: ['game-theory', 'prisoners-dilemma'] },
  { term: 'Subgame-perfect equilibrium', def: 'An equilibrium in which every player’s strategy is a best response at every point in the game, including points not reached. It rules out non-credible threats.', topics: ['game-theory'] },
  { term: 'Credible threat', def: 'A threat that the player would actually want to carry out when the time comes. Threats that would hurt the threatener are not credible.', topics: ['game-theory'] },
  { term: 'Commitment', def: 'An action taken in advance that changes a player’s own future payoffs, making a threat or promise credible, such as building spare capacity to deter entry.', topics: ['game-theory', 'stackelberg'] },
  { term: 'Bertrand competition', def: 'Oligopoly in which firms choose prices simultaneously and sell whatever is demanded at those prices. With identical goods the cheapest firm takes the whole market.', topics: ['oligopoly-compare', 'bertrand'] },
  { term: 'Bertrand paradox', def: 'With identical goods, equal constant costs and price competition, just two firms drive price down to marginal cost, the perfectly competitive outcome.', topics: ['oligopoly-compare', 'bertrand'] },
  { term: 'Strategic complements / substitutes', def: 'Strategic complements: a rival’s higher choice raises your best response (prices with differentiated goods), so reaction functions slope up. Strategic substitutes: it lowers your best response (Cournot quantities), so they slope down.', topics: ['bertrand', 'cournot'] },
  { term: 'Stackelberg model', def: 'Oligopoly in which a leader commits to its output first and a follower then chooses its best response. The leader picks the point on the follower’s reaction function that maximises its own profit. The guide examines the idea of Stackelberg leadership but not the model’s mathematics.', topics: ['oligopoly-compare', 'stackelberg'] },
  { term: 'First-mover advantage', def: 'The extra profit a firm earns by committing first. In the Stackelberg model the leader produces more and earns more than it would in Cournot, and the follower less.', topics: ['oligopoly-compare', 'stackelberg'] },
  { term: 'Isoprofit curve', def: 'All combinations of a firm’s own output and its rival’s output that give the firm the same profit. Curves closer to its own axis mean higher profit.', topics: ['stackelberg', 'cournot'] },
  { term: 'Inflection point of total cost', def: 'The output where TC switches from concave to convex. Marginal cost is at its minimum there, and diminishing marginal returns begin.', topics: ['cost-curves'] },
  { term: 'Reaction (best-response) function', def: 'A firm’s profit-maximising output for each possible output of its rival.', topics: ['cournot'] },
  { term: 'Nash equilibrium', def: 'A set of strategies in which no player can do better by changing their own strategy, given the others’ strategies.', topics: ['game-theory', 'cournot', 'prisoners-dilemma'] },
  { term: 'Collusion / cartel', def: 'Firms agreeing to restrict output and raise price, acting like a joint monopoly. Each member has an incentive to cheat.', topics: ['collusion', 'cournot', 'prisoners-dilemma'] },
  { term: 'Production quota', def: 'The share of the cartel’s total output each member agrees to produce. Quotas add up to the monopoly output.', topics: ['collusion'] },
  { term: 'Joint profit maximisation', def: 'Colluding firms choosing total output where industry MR = MC, as a single monopolist would, then dividing the profit.', topics: ['collusion'] },
  { term: 'Explicit collusion', def: 'A formal or informal agreement between firms to fix prices, share markets or limit output. Illegal under UK and EU competition law.', topics: ['collusion'] },
  { term: 'Tacit collusion', def: 'Firms coordinating on high prices without any agreement, for example by following a price leader or matching each other’s moves. Hard to prove in court.', topics: ['collusion', 'kinked-demand'] },
  { term: 'Price leadership', def: 'One firm, often the largest or lowest-cost, sets the price and the others follow. A common form of tacit collusion.', topics: ['price-leadership', 'collusion'] },
  { term: 'Dominant-firm price leadership', def: 'A large, usually low-cost firm sets the price as a monopolist on its residual demand (market demand minus a competitive fringe’s supply); the fringe firms take that price.', topics: ['price-leadership'] },
  { term: 'Barometric price leadership', def: 'Rivals follow the price changes of a firm that reads cost and demand conditions well, whether or not it is the largest firm.', topics: ['price-leadership'] },
  { term: 'Competitive fringe', def: 'The many small price-taking firms alongside a dominant firm. Each produces where the leader’s price equals its marginal cost.', topics: ['price-leadership'] },
  { term: 'Strategic variable', def: 'What firms compete over: quantities (Cournot, Stackelberg) or prices (Bertrand). The choice changes the predicted outcome sharply.', topics: ['oligopoly-compare', 'cournot', 'bertrand'] },
  { term: 'Price war', def: 'Rivals repeatedly undercutting each other, driving price towards marginal cost. The harshest punishment a cartel can threaten after cheating.', topics: ['collusion', 'bertrand'] },
  { term: 'Leniency programme', def: 'A competition-policy rule giving immunity or reduced fines to the first cartel member that reports the cartel, so each member fears being reported first.', topics: ['collusion'] },
  { term: 'Competition law', def: 'Rules that ban anti-competitive agreements such as cartels and abuse of a dominant position, enforced in the UK by the CMA and in the EU by the European Commission.', topics: ['collusion', 'monopoly'] },

  /* ── Factor markets and welfare ── */
  { term: 'Derived demand', def: 'Demand for an input that comes from demand for the output it helps produce, such as demand for labour.', topics: ['mvp-demand', 'trade-unions', 'labour-market'] },
  { term: 'Marginal revenue product (MRP)', def: 'The extra revenue from employing one more unit of an input: MRP_L = MP_L × MR. Under perfect competition in the output market it equals MVP_L = MP_L × P.', topics: ['mvp-demand', 'labour-market'] },
  { term: 'Value of the marginal product (MVP)', def: 'The market value of the extra output from one more worker: MVP_L = P × MP_L. For a firm in a competitive output market, the MVP_L curve is its labour demand curve.', topics: ['mvp-demand', 'labour-market'] },
  { term: 'Marginal factor cost (MFC)', def: 'The extra cost of hiring one more unit of an input. Equal to the wage in a competitive labour market; above the wage for a monopsonist.', topics: ['monopsony', 'bilateral-monopoly', 'labour-market'] },
  { term: 'Monopsony', def: 'A market with a single buyer, such as one large employer in a town. It hires fewer workers at a lower wage than a competitive market would.', topics: ['monopsony', 'labour-market'] },
  { term: 'Oligopsony', def: 'A market with a few large buyers, such as a few supermarkets buying from many farmers. Buyer power is weaker than under monopsony but works the same way.', topics: ['monopsony'] },
  { term: 'Rate of exploitation', def: 'Pigou’s measure of monopsony power: (MRP − w)/w, the gap between what the last worker adds to revenue and what they are paid, relative to the wage.', topics: ['monopsony'] },
  { term: 'Bilateral monopoly', def: 'A market with a single seller and a single buyer, such as a union bargaining with a monopsony employer. The price or wage lies in a range set by bargaining power.', topics: ['bilateral-monopoly'] },
  { term: 'Trade union', def: 'An organisation of workers that bargains collectively over pay and conditions. Acting as the only seller of labour, it behaves like a monopolist.', topics: ['trade-unions', 'bilateral-monopoly', 'labour-market'] },
  { term: 'Collective bargaining', def: 'Negotiation over pay and conditions between a union, on behalf of all its members, and an employer or employers’ association.', topics: ['bilateral-monopoly'] },
  { term: 'Countervailing power', def: 'Galbraith’s idea that power on one side of a market can be offset by power on the other, such as a union facing a monopsony employer.', topics: ['bilateral-monopoly', 'monopsony'] },
  { term: 'Compensating wage differential', def: 'Extra pay that makes up for a job’s disadvantages, such as danger, dirt or unsocial hours. It persists even when workers can move freely.', topics: ['wage-differentials'] },
  { term: 'Disequilibrium wage differential', def: 'A wage gap that exists only because workers cannot (yet) move to the better-paid job; it narrows as they move.', topics: ['wage-differentials'] },
  { term: 'Geographical immobility', def: 'Barriers to moving between regions for work, such as housing costs, family ties and lack of information.', topics: ['wage-differentials'] },
  { term: 'Occupational immobility', def: 'Barriers to changing occupation, such as lacking the skills or qualifications the new job needs.', topics: ['wage-differentials'] },
  { term: 'Non-competing groups', def: 'Occupations that need skills or qualifications few people have, so they form separate labour markets with their own wages.', topics: ['wage-differentials'] },
  { term: 'Transfer earnings', def: 'The minimum a worker must be paid to stay in a job: what they could earn in their next-best alternative. Pay above it is economic rent.', topics: ['wage-differentials'] },
  { term: 'Economic rent (labour)', def: 'Pay above a worker’s transfer earnings. Large when supply to a job is inelastic, as with scarce talent.', topics: ['wage-differentials'] },
  { term: 'Human capital', def: 'The skills, knowledge and health that make a worker productive, built up through education, training and experience.', topics: ['human-capital', 'wage-differentials'] },
  { term: 'Net present value (NPV)', def: 'The sum of future benefits minus costs, each discounted to today at the interest rate. An investment is worth making if its NPV is positive.', topics: ['human-capital'] },
  { term: 'Internal rate of return (IRR)', def: 'The discount rate at which an investment’s NPV is zero. Invest if it exceeds the interest rate.', topics: ['human-capital'] },
  { term: 'Age–earnings profile', def: 'How a person’s earnings change over their working life. Graduates earn little while studying but more later.', topics: ['human-capital'] },
  { term: 'General and specific training', def: 'General training raises productivity with any employer, so workers pay for it; specific training is useful only to one firm, so the firm shares the cost (Becker).', topics: ['human-capital'] },
  { term: 'Signalling (education)', def: 'Spence’s idea that education raises pay partly by showing employers who is able, not only by raising productivity.', topics: ['human-capital'] },
  { term: 'Closed shop', def: 'An arrangement where only union members may be employed. It restricts labour supply to the occupation; now illegal in the UK.', topics: ['trade-unions'] },
  { term: 'Union wage premium', def: 'How much more union members earn than similar non-union workers, as a percentage of the non-union wage.', topics: ['trade-unions'] },
  { term: 'Marshall’s rules of derived demand', def: 'Labour demand is less elastic when labour is hard to substitute, is a small share of costs, the product’s demand is inelastic, and other inputs are inelastically supplied.', topics: ['trade-unions'] },
  { term: 'Insider–outsider theory', def: 'Employed insiders, often through unions, push wages up for themselves, leaving unemployed outsiders unable to bid their way into jobs.', topics: ['trade-unions', 'efficiency-wages'] },
  { term: 'Efficiency wage', def: 'A wage above the market-clearing level that a firm pays because it raises productivity: less shirking, fewer quits, better applicants or more goodwill.', topics: ['efficiency-wages', 'wage-differentials'] },
  { term: 'Solow condition', def: 'The efficiency wage is where the elasticity of effort with respect to the wage equals 1, which minimises the wage per unit of effort.', topics: ['efficiency-wages'] },
  { term: 'Shirking model', def: 'Shapiro and Stiglitz: with imperfect monitoring, firms pay above the outside option so that the threat of dismissal deters shirking; unemployment is the discipline device.', topics: ['efficiency-wages'] },
  { term: 'Labour turnover', def: 'The rate at which workers leave and must be replaced. Higher pay reduces it, saving hiring and training costs.', topics: ['efficiency-wages'] },
  { term: 'Involuntary unemployment', def: 'People willing to work at the going wage who cannot find a job, for example because wages are held above the market-clearing level.', topics: ['efficiency-wages', 'trade-unions'] },
  { term: 'Labour market discrimination', def: 'Paying or treating equally productive workers differently because of a characteristic such as sex, ethnicity, disability or age.', topics: ['discrimination', 'wage-differentials'] },
  { term: 'Taste-based discrimination', def: 'Becker: employers, co-workers or customers dislike a group and act as if dealing with it carries an extra cost. Not in the EC1002 syllabus: the guide’s Block 9 reading excludes BVFD 11.8 (wage discrimination).', topics: ['discrimination'] },
  { term: 'Discrimination coefficient', def: 'In Becker’s model, d such that a prejudiced employer acts as if a worker from the disfavoured group costs w(1 + d). Not in the EC1002 syllabus: the guide’s Block 9 reading excludes BVFD 11.8 (wage discrimination).', topics: ['discrimination'] },
  { term: 'Statistical discrimination', def: 'Judging individuals by the average characteristics of their group because individual productivity is hard to observe. Not in the EC1002 syllabus: the guide’s Block 9 reading excludes BVFD 11.8 (wage discrimination).', topics: ['discrimination'] },
  { term: 'Occupational crowding', def: 'Excluding a group from some occupations crowds it into others, raising labour supply there and pushing wages down.', topics: ['discrimination', 'wage-differentials'] },
  { term: 'Unexplained pay gap', def: 'The part of a pay gap between groups not accounted for by measured characteristics such as experience and hours (Oaxaca decomposition). An upper bound on discrimination. Not in the EC1002 syllabus: the guide’s Block 9 reading excludes BVFD 11.8 (wage discrimination).', topics: ['discrimination'] },
  { term: 'Wage subsidy', def: 'A payment to employers (or in-work benefit to workers) per worker employed. It raises employment and take-home pay at a cost to the taxpayer.', topics: ['labour-policy'] },
  { term: 'Tax wedge', def: 'The gap between what an employer pays for a worker and what the worker takes home, caused by income tax and National Insurance.', topics: ['labour-policy'] },
  { term: 'Reservation wage', def: 'The lowest wage at which a person is willing to take a job. Higher out-of-work benefits raise it.', topics: ['labour-leisure', 'labour-policy', 'efficiency-wages'] },
  { term: 'Active labour market policy', def: 'Policies that help people into work, such as training, job-search support and hiring subsidies, rather than only paying benefits.', topics: ['labour-policy'] },
  { term: 'Pareto efficiency', def: 'An allocation where no one can be made better off without making someone else worse off.', topics: ['edgeworth'] },
  { term: 'Edgeworth box', def: 'A diagram showing every way to divide fixed totals of two goods between two people, with each person’s origin in an opposite corner.', topics: ['edgeworth'] },
  { term: 'Contract curve', def: 'The set of Pareto-efficient allocations in an Edgeworth box, where the two people’s indifference curves are tangent (MRS_A = MRS_B).', topics: ['edgeworth'] },
  { term: 'First welfare theorem', def: 'Under standard conditions, a competitive equilibrium is Pareto efficient.', topics: ['edgeworth'] },
  { term: 'Externality', def: 'A cost or benefit of an activity that falls on third parties who are not compensated and do not pay. Markets then over- or under-produce.', topics: ['positive-externality', 'externalities'] },
  { term: 'Marginal external cost (MEC)', def: 'The cost imposed on third parties by one more unit of output. MSC = MPC + MEC.', topics: ['externalities'] },
  { term: 'Marginal social cost / benefit (MSC, MSB)', def: 'Private cost or benefit plus external cost or benefit. The socially efficient output is where MSB = MSC.', topics: ['externalities'] },
  { term: 'Pigouvian tax', def: 'A per-unit tax equal to the marginal external cost at the efficient output. It makes producers face the full social cost.', topics: ['externalities'] },
  { term: 'Coase theorem', def: 'With clear property rights and low bargaining costs, private bargaining reaches the efficient outcome regardless of who holds the rights.', topics: ['externalities'] },
  { term: 'Public good', def: 'A good that is non-rival (one person’s use does not reduce another’s) and non-excludable (people cannot be stopped from using it), such as street lighting.', topics: ['public-goods', 'externalities'] },
  { term: 'Free-rider problem', def: 'People can enjoy a non-excludable good without paying, so private markets underprovide it.', topics: ['public-goods', 'externalities'] },
  { term: 'Gini coefficient', def: 'A measure of inequality from 0 (perfect equality) to 1 (one person has everything): the area between the line of equality and the Lorenz curve, divided by the total area under the line of equality.', topics: ['lorenz'] },
  { term: 'Lorenz curve', def: 'Plots the cumulative share of income earned by the poorest share of households.', topics: ['lorenz'] },

  /* ── Macro: measurement ── */
  { term: 'Gross domestic product (GDP)', def: 'The market value of all final goods and services produced within a country in a period: Y = C + I + G + (X − Z).', topics: ['national-income', 'growth-measure'] },
  { term: 'Gross national product (GNP)', def: 'GDP plus net income received from abroad (income earned by residents abroad minus income earned by foreigners at home).', topics: ['national-income'] },
  { term: 'Nominal vs real GDP', def: 'Nominal GDP values output at current prices; real GDP values it at constant base-year prices, removing the effect of inflation.', topics: ['growth-measure'] },
  { term: 'GDP deflator', def: 'Nominal GDP divided by real GDP, times 100. A price index covering all domestically produced goods.', topics: ['growth-measure'] },
  { term: 'Index number', def: 'A value expressed relative to a base period set to 100, so that changes read as percentages. A weighted index gives each item’s price change a weight equal to its share of spending.', topics: ['growth-measure'] },
  { term: 'Base year', def: 'The year whose prices are used to value output in real terms, and in which a price index equals 100.', topics: ['growth-measure'] },
  { term: 'Real income', def: 'Nominal income divided by the price level (CPI/100): what income can buy at base-year prices.', topics: ['growth-measure'] },
  { term: 'Consumer price index (CPI)', def: 'The cost of a fixed basket of consumer goods relative to a base year, used to measure consumer price inflation.', topics: ['growth-measure'] },
  { term: 'Shoe-leather costs', def: 'The cost of holding less cash when inflation is high: more trips to the bank and more time managing money.', topics: ['phillips'] },
  { term: 'Menu costs', def: 'The cost of changing prices often when inflation is high: reprinting price lists and menus, and updating systems.', topics: ['phillips'] },
  { term: 'Fiscal drag (bracket creep)', def: 'When tax allowances and brackets are fixed in nominal terms, inflation pushes people into higher real tax payments although their real income has not risen.', topics: ['phillips'] },
  { term: 'Inflation illusion', def: 'Confusing nominal and real changes, for example treating a pay rise that only matches inflation as a gain.', topics: ['phillips'] },
  { term: 'Anticipated and unanticipated inflation', def: 'Inflation people expect can be built into wages and interest rates, leaving mainly shoe-leather and menu costs. Unexpected inflation redistributes, for example from lenders to borrowers.', topics: ['phillips'] },
  { term: 'Inflation', def: 'A sustained rise in the general price level, measured as the percentage change in a price index.', topics: ['growth-measure', 'phillips'] },
  { term: 'Value added', def: 'The value of a firm’s output minus the value of intermediate inputs bought from other firms. Summing value added avoids double counting.', topics: ['national-income'] },
  { term: 'Intermediate goods', def: 'Goods used up in producing other goods. They are excluded from GDP to avoid double counting.', topics: ['national-income'] },
  { term: 'Circular flow of income', def: 'Model of income flowing from firms to households as factor payments and back to firms as spending, with leakages and injections.', topics: ['national-income', 'injections-leakages'] },
  { term: 'Leakages (withdrawals)', def: 'Income not passed on as spending on domestic output: saving (S), net taxes (NT) and imports (Z).', topics: ['national-income', 'injections-leakages'] },
  { term: 'Injections', def: 'Spending on domestic output that does not come from households’ consumption: investment (I), government purchases (G) and exports (X).', topics: ['national-income', 'injections-leakages'] },
  { term: 'Net taxes (NT)', def: 'Taxes minus transfer payments (such as benefits).', topics: ['national-income', 'keynesian-cross'] },
  { term: 'Disposable income (Y_d)', def: 'Income after net taxes: Y_d = Y − NT. Households either consume or save it.', topics: ['keynesian-cross', 'national-income'] },
  { term: 'Unemployment rate', def: 'The unemployed as a percentage of the labour force (employed plus those actively seeking work).', topics: ['unemployment', 'growth-measure', 'phillips'] },
  { term: 'Frictional / structural / cyclical unemployment', def: 'Frictional: between jobs. Structural: mismatch of skills or location with available jobs. Cyclical: caused by low aggregate demand in a downturn.', topics: ['unemployment', 'natural-rate', 'phillips'] },
  { term: 'Labour force', def: 'Everyone in work plus the unemployed (without work, available and actively looking). People not looking are economically inactive.', topics: ['unemployment'] },
  { term: 'Employment rate', def: 'The employed as a percentage of the working-age population (e = E/P).', topics: ['unemployment'] },
  { term: 'Inactivity rate', def: 'People of working age who are neither working nor looking for work (not in the labour force), as a percentage of the working-age population. It equals 100% minus the participation rate.', topics: ['unemployment'] },
  { term: 'Participation rate', def: 'The labour force as a percentage of the working-age population.', topics: ['unemployment'] },
  { term: 'ILO unemployment', def: 'The international definition used in the Labour Force Survey: without a job, available to start within two weeks, and looked for work in the last four weeks.', topics: ['unemployment'] },
  { term: 'Claimant count', def: 'The number of people claiming unemployment-related benefits. It usually counts fewer people than the ILO measure.', topics: ['unemployment'] },
  { term: 'Discouraged workers', def: 'People who want a job but have stopped looking because they think none is available. They count as inactive, not unemployed.', topics: ['unemployment'] },
  { term: 'Steady-state unemployment', def: 'The rate at which flows into unemployment equal flows out: u* = j/(j + h), with j the job-loss rate and h the hiring rate (jE = hU).', topics: ['unemployment'] },
  { term: 'Long-term unemployment', def: 'Unemployment lasting a year or more. Skills and motivation decay, so job-finding rates fall the longer a spell lasts.', topics: ['unemployment', 'natural-rate'] },
  { term: 'Hysteresis', def: 'When a temporary rise in unemployment raises the natural rate itself, for example because the long-term unemployed lose skills.', topics: ['natural-rate', 'unemployment'] },
  { term: 'Wage-setting (WS) curve', def: 'The real wage workers can secure at each level of employment; higher when unemployment is lower or when benefits and union power are greater.', topics: ['natural-rate'] },
  { term: 'Price-setting (PS) curve', def: 'The real wage consistent with firms’ desired mark-up over labour costs: A/(1 + μ).', topics: ['natural-rate'] },

  /* ── Macro: demand side ── */
  { term: 'Consumption function', def: 'The relationship between consumption and disposable income: C = A + cY_d, where A is autonomous consumption and c is the MPC.', topics: ['keynesian-cross'] },
  { term: 'Marginal propensity to consume (MPC)', def: 'The fraction of an extra unit of disposable income that is spent on consumption.', topics: ['keynesian-cross'] },
  { term: 'Marginal propensity to save (MPS)', def: 'The fraction of an extra unit of disposable income that is saved. MPC + MPS = 1.', topics: ['keynesian-cross'] },
  { term: 'Marginal propensity to import (z)', def: 'The fraction of an extra unit of income spent on imports.', topics: ['keynesian-cross', 'injections-leakages'] },
  { term: 'Autonomous spending', def: 'Spending that does not depend on current income, such as autonomous consumption, planned investment, government purchases and exports.', topics: ['keynesian-cross'] },
  { term: 'Aggregate demand (AD)', def: 'Total planned spending on domestic output: C + I + G + (X − Z). In the AD–AS model, as in the guide, it is drawn against inflation: from the policy rule r = gπ and the IS schedule r = h − kY, AD is π = (h − kY)/g.', topics: ['keynesian-cross', 'ad-as'] },
  { term: 'Multiplier', def: 'The change in equilibrium output divided by the change in autonomous spending that caused it. In an open economy with taxes, K = 1 / [1 − c(1 − t) + z].', topics: ['keynesian-cross', 'injections-leakages'] },
  { term: 'Balanced-budget multiplier', def: 'The effect on output of equal increases in government spending and lump-sum taxes. In the simple model it equals 1.', topics: ['keynesian-cross'] },
  { term: 'Deflationary (recessionary) gap', def: 'The amount by which aggregate demand falls short of output at full employment, measured vertically at Y_f on the 45° diagram.', topics: ['keynesian-cross'] },
  { term: 'Inflationary gap', def: 'The amount by which aggregate demand exceeds output at full employment.', topics: ['keynesian-cross'] },
  { term: 'Paradox of thrift', def: 'An attempt by everyone to save more lowers income, so total saving may not rise.', topics: ['keynesian-cross'] },
  { term: 'Fiscal policy', def: 'Changes in government spending or taxation to influence aggregate demand.', topics: ['keynesian-cross', 'is-mp'] },
  { term: 'Crowding out', def: 'Higher government borrowing or spending raises interest rates and reduces private investment, offsetting part of the fiscal stimulus.', topics: ['loanable-funds', 'money-ismp'] },
  { term: 'IS curve', def: 'Combinations of output and the real interest rate at which the goods market is in equilibrium. It slopes down because a lower rate raises investment.', topics: ['is-mp', 'money-ismp'] },
  { term: 'MP curve (monetary policy rule)', def: 'Shows the real interest rate the central bank sets at each level of output (flat if it fixes r, upward-sloping if it raises r as output rises).', topics: ['is-mp', 'money-ismp'] },
  { term: 'LM curve', def: 'Combinations of output and the interest rate at which the money market clears for a given money supply. It slopes up.', topics: ['money-ismp'] },
  { term: 'Money demand (liquidity preference)', def: 'How much money people want to hold: it rises with income (transactions) and falls with the interest rate (the opportunity cost of holding money).', topics: ['money-market', 'money-ismp'] },
  { term: 'Monetary policy', def: 'Central bank action, usually setting a short-term interest rate, to influence spending and inflation.', topics: ['is-mp', 'money-ismp', 'money-market'] },
  { term: 'Nominal vs real interest rate', def: 'The nominal rate is the quoted rate; the real rate removes expected inflation: r ≈ i − πᵉ (the Fisher equation).', topics: ['is-mp', 'money-market'] },
  { term: 'Zero lower bound', def: 'Nominal interest rates cannot be cut much below zero, which limits conventional monetary policy in deep recessions.', topics: ['investment-trap', 'money-ismp'] },
  { term: 'Functions of money', def: 'The guide lists four: medium of exchange (accepted in payment), store of value (it holds purchasing power over time), unit of account (prices are quoted in it) and standard of deferred payment (debts are written in it).', topics: ['money-market'] },
  { term: 'Monetary base (H)', def: 'Currency in circulation plus banks’ reserves: H = C + R. The central bank controls it directly; it is also called narrow money or high-powered money.', topics: ['money-market'] },
  { term: 'Fractional-reserve banking', def: 'Banks keep only a fraction of deposits as reserves and lend out the rest. Each loan is redeposited, creating new deposits, so the money supply is a multiple of the monetary base.', topics: ['money-market'] },
  { term: 'Reserve ratio (c_b)', def: 'The fraction of deposits banks hold as reserves (c_b in BVFD). A higher reserve ratio lowers the money multiplier M/H = (c_p + 1)/(c_p + c_b).', topics: ['money-market'] },
  { term: 'Cash-to-deposit ratio (c_p)', def: 'The cash the public holds relative to its bank deposits (c_p in BVFD). Cash held outside banks cannot be re-lent, so a higher ratio lowers the money multiplier.', topics: ['money-market'] },
  { term: 'Open market operations', def: 'Central bank purchases or sales of government bonds. A purchase adds reserves (raising the monetary base and lowering interest rates); a sale does the opposite.', topics: ['money-market'] },
  { term: 'Velocity of money (V)', def: 'The average number of times a unit of money is spent on final output in a year: V = PY/M. Part of the quantity theory, which is not part of EC1002 (guide, Block 17).', topics: ['money-market'] },
  { term: 'Liquidity', def: 'How quickly and cheaply an asset can be turned into money without losing value. Cash is the most liquid asset.', topics: ['money-market'] },
  { term: 'Lender of last resort', def: 'The central bank’s role of lending to solvent banks that face a sudden shortage of liquidity, to stop bank runs spreading.', topics: ['money-market'] },
  { term: 'Liquidity crisis', def: 'A bank whose assets exceed its liabilities cannot turn them into cash fast enough to pay depositors who want their money. Central bank lending can solve it.', topics: ['money-market'] },
  { term: 'Solvency crisis', def: 'A bank’s liabilities exceed its assets, so it is bankrupt. Lending more to it does not solve the problem; it needs new capital or must close.', topics: ['money-market'] },
  { term: 'Transactions motive', def: 'Holding money to pay for planned purchases, because income and spending do not arrive at the same time. It rises with income.', topics: ['money-market'] },
  { term: 'Precautionary motive', def: 'Holding money to meet unexpected payments.', topics: ['money-market'] },
  { term: 'Asset motive', def: 'Holding money as a low-risk store of wealth in a portfolio with riskier assets. The cost is the interest forgone.', topics: ['money-market'] },
  { term: 'Bank run', def: 'Many depositors withdraw at once because they fear the bank will fail. Because banks hold only fractional reserves, a run can bring down even a sound bank.', topics: ['money-market'] },
  { term: 'Quantity theory of money', def: 'MV = PY. If velocity and real output are stable, faster money growth leads to higher inflation. Not part of EC1002: the guide (Block 17) leaves it out.', topics: ['money-market'] },
  { term: 'Money multiplier', def: 'The ratio of broad money to the monetary base: M/H = (c_p + 1)/(c_p + c_b), where c_b is the banks’ reserve ratio and c_p the public’s cash-to-deposit ratio. With no cash outside banks it is 1/c_b.', topics: ['money-market'] },

  /* ── Macro: supply side, inflation, growth ── */
  { term: 'Potential output (Y*)', def: 'The output the economy produces when resources are fully employed at normal rates, with unemployment at its natural rate.', topics: ['ad-as'] },
  { term: 'Output gap', def: 'The percentage difference between actual and potential output: (Y − Y*)/Y* × 100.', topics: ['ad-as', 'adas-phillips'] },
  { term: 'Short-run aggregate supply (SRAS)', def: 'Output firms supply at each inflation rate in the short run, while expectations are fixed: Y = Y* + α(π − πᵉ), or π = πᵉ + γ(Y − Y*) with γ = 1/α.', topics: ['ad-as'] },
  { term: 'Long-run aggregate supply (LRAS)', def: 'Vertical at potential output: in the long run output does not depend on inflation.', topics: ['ad-as'] },
  { term: 'Demand shock', def: 'An unexpected change in aggregate demand, such as a fiscal stimulus or a fall in confidence. It moves the economy along SRAS.', topics: ['ad-as', 'adas-phillips'] },
  { term: 'Supply shock', def: 'An unexpected change in costs or productivity, such as an oil price spike. It shifts SRAS.', topics: ['ad-as', 'adas-phillips'] },
  { term: 'Stagflation', def: 'Rising inflation together with falling output and rising unemployment, typically after an adverse supply shock.', topics: ['inflation-types', 'ad-as', 'phillips'] },
  { term: 'Taylor rule', def: 'A guide to setting interest rates: r − r* = a(π − π*) + b(Y − Y*), with a, b > 0 (BVFD Maths 24.1). The bank raises rates when inflation or output is above target; nominal rates rise by (1 + a) times any rise in inflation.', topics: ['ad-as', 'money-market'] },
  { term: 'Phillips curve', def: 'The short-run trade-off between inflation and unemployment. The expectations-augmented version is π = πᵉ − b(u − u*) + v, where v is a supply shock.', topics: ['phillips', 'adas-phillips'] },
  { term: 'Natural rate of unemployment / NAIRU', def: 'The unemployment rate at which inflation equals expected inflation, so inflation is stable. The long-run Phillips curve is vertical there.', topics: ['natural-rate', 'phillips'] },
  { term: 'Adaptive expectations', def: 'Expected inflation is based on past inflation, for example πᵉ_t = π_{t−1}.', topics: ['phillips', 'adas-phillips'] },
  { term: 'Okun’s law', def: 'The link between the output gap and unemployment: Y − Y* = −h(u − u*), with h > 0 (the guide’s and BVFD’s form). A common rule of thumb is that each point of unemployment above the natural rate costs about 2% of output.', topics: ['ad-as', 'adas-phillips'] },
  { term: 'Sacrifice ratio', def: 'The percentage of a year’s output lost for each percentage point reduction in inflation.', topics: ['phillips'] },
  { term: 'Steady state (Solow)', def: 'The capital per effective worker at which investment exactly covers effective depreciation, so k stops changing: s·f(k) = (δ + n + t)k.', topics: ['solow'] },
  { term: 'Golden rule', def: 'The steady state with the highest consumption per worker, where the marginal product of capital equals δ + n + t.', topics: ['solow'] },
  { term: 'Total factor productivity (TFP)', def: 'The part of output growth not explained by growth in capital and labour, usually attributed to technology.', topics: ['solow'] },
  { term: 'Conditional convergence', def: 'Economies with similar saving, population growth and technology converge to similar income paths, poorer ones growing faster.', topics: ['solow'] },
  { term: 'Rule of 70', def: 'A quantity growing at g% a year doubles in about 70/g years.', topics: ['growth-measure'] },

  /* ── Open economy ── */
  { term: 'Managed float (dirty float)', def: 'A floating exchange rate in which the central bank intervenes in the foreign exchange market from time to time to smooth or steer the rate, without committing to a peg.', topics: ['forex'] },
  { term: 'Nominal exchange rate (e)', def: 'The price of one currency in terms of another. Here quoted as foreign currency per unit of domestic currency, so a rise is an appreciation.', topics: ['forex'] },
  { term: 'Real exchange rate (RER)', def: 'The relative price of domestic and foreign goods: RER = e·P/P*.', topics: ['forex'] },
  { term: 'Appreciation / depreciation', def: 'A rise / fall in the value of a currency under a floating exchange rate. Appreciation makes exports dearer abroad and imports cheaper at home.', topics: ['forex'] },
  { term: 'Devaluation / revaluation', def: 'A deliberate cut / rise in a fixed exchange rate by the authorities.', topics: ['forex'] },
  { term: 'Floating exchange rate', def: 'The rate is set by supply and demand in the foreign exchange market without official intervention.', topics: ['forex'] },
  { term: 'Fixed (pegged) exchange rate', def: 'The central bank holds the rate at a target by buying or selling its own currency with foreign reserves.', topics: ['forex'] },
  { term: 'Purchasing power parity (PPP)', def: 'The path of the nominal exchange rate that keeps the real exchange rate constant, so exchange rate changes offset inflation differences (BVFD). In its simplest form the same basket costs the same everywhere: e = P*/P.', topics: ['forex'] },
  { term: 'Balance of payments', def: 'The record of a country’s transactions with the rest of the world: the current account plus the capital and financial accounts sum to zero.', topics: ['forex', 'tariff'] },
  { term: 'Current account', def: 'Net exports of goods and services plus net primary income and net transfers from abroad.', topics: ['forex'] },
  { term: 'Marshall–Lerner condition', def: 'A depreciation improves the trade balance only if the sum of the absolute export and import price elasticities exceeds 1.', topics: ['j-curve', 'forex'] },
  { term: 'Tariff', def: 'A tax on imports. It raises the domestic price, helps domestic producers and raises revenue, but costs consumers more and creates deadweight loss. Trade policy is not covered in the EC1002 subject guide.', topics: ['tariff'] },
  { term: 'Import quota', def: 'A limit on the quantity of imports. Same price effect as a tariff, but the revenue goes to licence holders instead of the government. Trade policy is not covered in the EC1002 subject guide.', topics: ['import-quota', 'tariff'] },
  { term: 'Corner solution', def: 'An optimum at the edge of the budget line, buying none of one good. Happens with perfect substitutes or when one good is poor value at every bundle.', topics: ['special-preferences'] },
  { term: 'Perfect substitutes', def: 'Goods the consumer will swap at a constant rate, so indifference curves are straight lines and the consumer usually buys only one of them.', topics: ['special-preferences'] },
  { term: 'Perfect complements', def: 'Goods always used in fixed proportions (left and right shoes), so indifference curves are L-shaped and there is no substitution effect.', topics: ['special-preferences'] },
  { term: 'Intertemporal budget constraint', def: 'The present value of consumption must equal the present value of income: c₁ + c₂/(1 + r) = y₁ + y₂/(1 + r).', topics: ['intertemporal'] },
  { term: 'Consumption smoothing', def: 'Using saving and borrowing to keep consumption steadier than income over time.', topics: ['intertemporal'] },
  { term: 'Backward-bending labour supply', def: 'A labour supply curve that slopes up at low wages and bends back at high wages, where the income effect (more leisure) outweighs the substitution effect.', topics: ['labour-leisure'] },
  { term: 'Marginal external benefit (MEB)', def: 'The benefit to third parties of one more unit. With positive externalities, MSB = MPB + MEB.', topics: ['positive-externality'] },
  { term: 'Merit good', def: 'A good that is under-consumed in a free market, because of external benefits or because people underestimate their own benefit (education, healthcare).', topics: ['positive-externality'] },
  { term: 'Non-rival', def: 'One person’s consumption does not reduce what is available to others (a TV broadcast).', topics: ['public-goods'] },
  { term: 'Non-excludable', def: 'People cannot be prevented from consuming the good, even if they do not pay.', topics: ['public-goods', 'commons'] },
  { term: 'Lindahl prices', def: 'Charging each person their own marginal benefit at the efficient quantity of a public good; the prices add up to marginal cost.', topics: ['public-goods'] },
  { term: 'Common resource', def: 'A good that is rival but non-excludable, such as fish in the sea, so it tends to be overused.', topics: ['commons'] },
  { term: 'Tragedy of the commons', def: 'The overuse of a common resource because each user ignores the cost their use imposes on others.', topics: ['commons'] },
  { term: 'Tradable quota', def: 'A right to use a set amount of a resource (a fish catch, an emission) that can be bought and sold, capping total use efficiently.', topics: ['commons'] },
  { term: 'Asymmetric information', def: 'When one side of a transaction knows more than the other, as a seller does about a used car’s quality.', topics: ['lemons'] },
  { term: 'Adverse selection', def: 'Hidden information before a deal means the worst types are keenest to trade, so the market can shrink or collapse (the market for lemons).', topics: ['lemons'] },
  { term: 'Moral hazard', def: 'Hidden action after a deal: once protected, people take more risks (an insured driver drives less carefully).', topics: ['lemons'] },
  { term: 'Signalling', def: 'An action by the informed side that reveals quality, such as a warranty or a qualification.', topics: ['lemons', 'human-capital'] },
  { term: 'Quota rent', def: 'The gain to whoever holds import licences under a quota: (domestic price − world price) × quota. Trade policy is not covered in the EC1002 subject guide.', topics: ['import-quota'] },
  { term: 'Voluntary export restraint (VER)', def: 'An agreement by an exporting country to limit its exports; the quota rent goes to foreign firms. Trade policy is not covered in the EC1002 subject guide.', topics: ['import-quota'] },
  { term: 'Demand-pull inflation', def: 'Inflation caused by aggregate demand growing faster than the economy’s capacity to produce.', topics: ['inflation-types'] },
  { term: 'Cost-push inflation', def: 'Inflation caused by rising costs (energy, wages, import prices) shifting short-run aggregate supply up.', topics: ['inflation-types'] },
  { term: 'Wage–price spiral', def: 'Higher prices lead workers to demand higher wages, which firms pass on in higher prices, and so on.', topics: ['inflation-types'] },
  { term: 'Laffer curve', def: 'The relationship between the tax rate and tax revenue: zero at 0% and 100%, with a peak in between.', topics: ['laffer'] },
  { term: 'Liquidity trap', def: 'When interest rates are at (or near) zero, so extra money is simply held and monetary policy cannot lower rates further.', topics: ['investment-trap'] },
  { term: 'Marginal efficiency of capital (MEC)', def: 'The expected rate of return on an extra unit of investment; firms invest while it exceeds the interest rate.', topics: ['investment-trap'] },
  { term: 'Animal spirits', def: 'Keynes’s term for the waves of optimism and pessimism that drive investment.', topics: ['investment-trap'] },
  { term: 'Uncovered interest parity (UIP)', def: 'Expected returns on deposits in two currencies are equal: i = i* + expected depreciation of the home currency. Not on the EC1002 syllabus: the guide says interest parity is covered in EC2065.', topics: ['interest-parity'] },
  { term: 'Capital flows', def: 'Movements of money between countries to buy financial assets, driven largely by differences in expected returns.', topics: ['interest-parity'] },
  { term: 'J-curve', def: 'The path of the trade balance after a depreciation: it worsens at first, then improves as trade volumes respond.', topics: ['j-curve'] },
  { term: 'Investment', def: 'Firms’ spending on new capital goods (machines, buildings) and additions to inventories. In macro models it is an injection, and planned investment falls as the real interest rate rises.', topics: ['keynesian-cross', 'injections-leakages', 'is-mp', 'investment-trap'] },
  { term: 'Saving', def: 'The part of disposable income that households do not spend: S = Y_d − C. It is a leakage from the circular flow.', topics: ['keynesian-cross', 'injections-leakages', 'loanable-funds'] },
  { term: 'Central bank', def: 'The bank of the government and of commercial banks. It controls the monetary base, sets the policy interest rate and acts as lender of last resort; in the UK, the Bank of England.', topics: ['money-market', 'is-mp', 'money-ismp'] },
  { term: 'Broad money / narrow money', def: 'Narrow money (the monetary base, H) is cash in circulation plus banks’ reserves. Broad money (M4 in the UK) adds bank and building-society deposits. The money multiplier is the ratio of broad to narrow money.', topics: ['money-market'] },
  { term: 'Money supply', def: 'Broad money: cash held by the public plus bank deposits, M = C + D.', topics: ['money-market', 'money-ismp'] },
  { term: 'Monetary transmission mechanism', def: 'The channels through which a change in the policy interest rate reaches spending and inflation: borrowing costs, asset prices, the exchange rate and expectations.', topics: ['money-market', 'is-mp'] },
  { term: 'Quantitative easing (QE)', def: 'Large-scale purchases of financial assets by the central bank, paid for with new reserves, used when interest rates are close to zero.', topics: ['money-market', 'investment-trap'] },
  { term: 'Inflation target', def: 'The inflation rate the central bank aims for (2% in the UK). It adjusts interest rates to keep inflation close to the target.', topics: ['ad-as', 'phillips', 'adas-phillips'] },
  { term: 'Long-run Phillips curve (LRPC)', def: 'Vertical at the natural rate of unemployment: once expectations adjust, inflation that people foresee has no lasting effect on unemployment.', topics: ['phillips', 'adas-phillips'] },
  { term: 'Classical model', def: 'The macro model in which wages and prices are fully flexible, so output stays at potential and the aggregate supply curve is vertical.', topics: ['ad-as'] },
  { term: 'Supply-side policies', def: 'Policies that raise potential output or lower the natural rate of unemployment, for example by improving incentives to work and invest, training, or better job matching.', topics: ['ad-as', 'natural-rate', 'solow'] },
  { term: 'Automatic stabilisers', def: 'Taxes and benefits that change with income without any policy decision, such as income tax and unemployment benefit. They reduce the multiplier and so damp fluctuations in output.', topics: ['keynesian-cross', 'injections-leakages'] },
  { term: 'Structural (cyclically adjusted) budget', def: 'The budget balance the government would have if output were at potential. It measures the fiscal stance with the effect of the business cycle removed.', topics: ['keynesian-cross'] },
  { term: 'Budget deficit / national debt', def: 'The budget deficit is government spending minus revenue in a year (G − NT, plus debt interest); the national debt is the stock of past borrowing not yet repaid.', topics: ['keynesian-cross', 'loanable-funds'] },
  { term: 'Production function', def: 'The maximum output a firm or economy can produce from given inputs with existing technology, for example Q = f(K, L).', topics: ['isoquant', 'solow'] },
  { term: 'Economic growth', def: 'A rise in an economy’s capacity to produce, measured by the growth rate of real GDP (or real GDP per person).', topics: ['solow', 'growth-measure'] },
  { term: 'Technical progress', def: 'New knowledge that lets the same inputs produce more output. In the Solow model labour-augmenting technical progress at rate t is the source of lasting growth in output per worker.', topics: ['solow'] },
  { term: 'Romer (AK) model', def: 'An endogenous growth model with constant returns to capital, y = Ak. Output per worker grows at sA − (δ + n), so saving, education and research change the long-run growth rate.', topics: ['romer-ak'] },
  { term: 'Endogenous growth', def: 'Growth theories in which the long-run growth rate depends on economic choices such as saving, research and education, because capital in a broad sense does not face diminishing returns (as in Y = AK).', topics: ['solow'] },
  { term: 'Welfare economics', def: 'The normative study of how well an economy allocates resources, using criteria such as Pareto efficiency and equity.', topics: ['edgeworth', 'externalities', 'public-goods'] },
  { term: 'General equilibrium', def: 'Equilibrium in all markets at once, taking account of how a change in one market spills over into others.', topics: ['edgeworth'] },
  { term: 'Distortion and second best', def: 'A distortion exists when society’s marginal cost and marginal benefit differ, as with taxes, monopoly or externalities. If one distortion cannot be removed, removing another may not raise efficiency (the theory of the second best).', topics: ['externalities', 'positive-externality'] },
  { term: 'Horizontal and vertical equity', def: 'Horizontal equity treats people in the same position the same way. Vertical equity treats people differently to reduce inequality, for example through progressive taxes.', topics: ['lorenz', 'tax-incidence'] },
  { term: 'Concentration ratio', def: 'The share of an industry’s output or sales produced by its N largest firms (an N-firm concentration ratio), used to judge how concentrated a market is.', topics: ['monopolistic-competition', 'oligopoly-compare'] },
  { term: 'Minimum wage', def: 'A legal floor on wages. Above the market wage in a competitive market it reduces employment; in monopsony a minimum wage set between the two can raise both wages and employment.', topics: ['labour-market', 'monopsony', 'labour-policy'] },
  { term: 'Exchange rate regime', def: 'How a country’s exchange rate is determined: floating (set by the market), fixed (held by the central bank) or something in between.', topics: ['forex'] },
  { term: 'Trade balance', def: 'The value of exports minus imports of goods and services (net exports).', topics: ['forex', 'j-curve'] },
  { term: 'Capital account', def: 'The part of the balance of payments that records capital transfers, such as debt forgiveness. Purchases and sales of financial assets go in the financial account.', topics: ['forex'] },
  { term: 'Financial account', def: 'The part of the balance of payments that records cross-border purchases and sales of financial assets.', topics: ['forex'] },
  { term: 'Internal and external balance', def: 'Internal balance is output at potential with stable inflation; external balance is a current account that is sustainable (in the simplest case, zero).', topics: ['forex', 'j-curve'] },
  { term: 'Capital controls', def: 'Limits on moving funds into or out of a country. They let domestic interest rates differ from world rates, giving a country with a fixed exchange rate some room for its own monetary policy.', topics: ['open-policy'] },
  { term: 'Internal balance', def: 'Output at its potential level, with stable inflation.', topics: ['open-policy'] },
  { term: 'External balance', def: 'A current account that can be sustained, without persistent deficits that build up foreign debt or drain reserves.', topics: ['open-policy'] },
  { term: 'Perfect capital mobility', def: 'Funds move freely and very quickly between currencies whenever expected returns differ, so interest rates cannot differ for long without an expected exchange rate change.', topics: ['forex'] },
];
